package org.brightstats.desktop;

import java.util.*;
import com.google.gson.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.stats.*;

final class ProcessDialog {
    enum Template {PARALLEL_MEDIATION,SERIAL_MEDIATION,MODERATION,THREE_WAY_MODERATION,FIRST_STAGE_MODERATED_MEDIATION,SECOND_STAGE_MODERATED_MEDIATION,BOTH_STAGES_MODERATED_MEDIATION;
        @Override public String toString(){return switch(this){case PARALLEL_MEDIATION->"Simple / parallel mediation";case SERIAL_MEDIATION->"Serial mediation (listed mediator order)";case MODERATION->"Two-way moderation";case THREE_WAY_MODERATION->"Three-way moderation";case FIRST_STAGE_MODERATED_MEDIATION->"First-stage moderated mediation";case SECOND_STAGE_MODERATED_MEDIATION->"Second-stage moderated mediation";case BOTH_STAGES_MODERATED_MEDIATION->"Both-stage moderated mediation";};}}
    record Settings(PathProcess.Model model,PathProcess.Options options,List<PathProcess.Probe> probes,Bootstrap.Options bootstrap){Settings{Objects.requireNonNull(model);Objects.requireNonNull(options);probes=List.copyOf(probes);Objects.requireNonNull(bootstrap);}}
    private final Dialog<Settings> dialog=new Dialog<>();private final ComboBox<Template> template=new ComboBox<>();private final ComboBox<String> x=new ComboBox<>(),y=new ComboBox<>(),w=new ComboBox<>(),z=new ComboBox<>();private final ListView<String> mediators=new ListView<>(),controls=new ListView<>();private final TextField mediatorOrder=new TextField(),wValues=new TextField(),zValues=new TextField(),confidence=new TextField(),samples=new TextField(),seed=new TextField();private final ComboBox<PathProcess.Metric> metric=new ComboBox<>();private final ComboBox<RobustRegression.Covariance> covariance=new ComboBox<>();private final ComboBox<RegressionBootstrap.Convention> convention=new ComboBox<>();private final ComboBox<BootstrapIntervals.Method> interval=new ComboBox<>();private final CheckBox useControls=new CheckBox("Include selected controls in every response equation"),custom=new CheckBox("Use custom path/probe specification below"),twoSided=new CheckBox("Two-sided bootstrap inference");private final TextArea modelJson=new TextArea(),probeJson=new TextArea();private Settings result;
    ProcessDialog(Window owner,List<String> names,double[][] data,Settings previous,boolean resampling){
        if(names.size()<3)throw new IllegalArgumentException("Import at least three variables for process analysis.");dialog.initOwner(owner);dialog.setTitle(resampling?"Conditional process bootstrap":"Path, mediation and moderation analysis");template.getItems().setAll(Template.values());template.setValue(Template.PARALLEL_MEDIATION);for(var combo:List.of(x,y,w,z))combo.getItems().setAll(names);x.getSelectionModel().select(0);y.getSelectionModel().select(Math.min(3,names.size()-1));w.getSelectionModel().select(Math.min(4,names.size()-1));z.getSelectionModel().select(Math.min(5,names.size()-1));mediators.getItems().setAll(names);mediators.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);mediators.getSelectionModel().select(1);mediators.setPrefHeight(135);controls.getItems().setAll(names);controls.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);controls.setPrefHeight(135);mediatorOrder.setPromptText("Optional ordered column numbers, e.g. 2,3 (one-based)");wValues.setText(defaultValues(data,w.getSelectionModel().getSelectedIndex()));zValues.setText(defaultValues(data,z.getSelectionModel().getSelectedIndex()));w.valueProperty().addListener((property,old,value)->wValues.setText(defaultValues(data,names.indexOf(value))));z.valueProperty().addListener((property,old,value)->zValues.setText(defaultValues(data,names.indexOf(value))));var options=previous==null?PathProcess.Options.defaults():previous.options();var boot=previous==null?new Bootstrap.Options(5000,42,.95):previous.bootstrap();metric.getItems().setAll(PathProcess.Metric.values());metric.setValue(options.metric());covariance.getItems().setAll(RobustRegression.Covariance.values());covariance.setValue(options.covariance());confidence.setText(Double.toString(options.confidence()));useControls.setSelected(options.considerControls());samples.setText(Integer.toString(boot.samples()));seed.setText(Long.toString(boot.seed()));convention.getItems().setAll(RegressionBootstrap.Convention.values());convention.setValue(boot.convention());interval.getItems().setAll(BootstrapIntervals.Method.values());interval.setValue(boot.interval());twoSided.setSelected(boot.twoSided());
        Label guidance=UiAppearance.label("Build an observed-variable model using raw data columns. The dataset column order supplies the default mediator order; enter one-based column numbers to change it. Moderators must be exogenous and distinct from focal/mediator/control roles. Product terms automatically include lower-order terms. Probe values are original data units.");guidance.setWrapText(true);VBox builder=new VBox(8,guidance,UiAppearance.label("Model recipe"),template,row("Focal source X",x,"Outcome Y",y),UiAppearance.label("Select mediator variables (Ctrl-click for multiple)"),mediators,mediatorOrder,UiAppearance.label("Controls (Ctrl-click for multiple)"),controls,useControls,row("Moderator W",w,"Moderator Z (three-way only)",z),row("W probe values",wValues,"Z probe values",zValues));builder.setPadding(new Insets(12));
        modelJson.setPrefRowCount(13);probeJson.setPrefRowCount(6);if(previous!=null){custom.setSelected(true);modelJson.setText(new GsonBuilder().setPrettyPrinting().create().toJson(previous.model()));probeJson.setText(new GsonBuilder().setPrettyPrinting().create().toJson(previous.probes()));}else{modelJson.setText("{\"source\":0,\"target\":2,\"paths\":[{\"source\":0,\"target\":1,\"moderators\":[]},{\"source\":1,\"target\":2,\"moderators\":[]},{\"source\":0,\"target\":2,\"moderators\":[]}],\"controls\":[]}");probeJson.setText("[]");}Label advancedHelp=UiAppearance.label("Custom model indexes are zero-based. Each path has source, target and up to two moderator column indexes. Probe objects have a unique name and a values map from moderator column index to raw value. Empty probes evaluate the original moderator means. Cycles and endogenous moderators are rejected.");advancedHelp.setWrapText(true);VBox advanced=new VBox(8,advancedHelp,UiAppearance.label("Path model"),modelJson,UiAppearance.label("Probe conditions"),probeJson);advanced.setPadding(new Insets(12));VBox estimation=new VBox(8,UiAppearance.label("Data metric"),metric,UiAppearance.label("Equation coefficient covariance"),covariance,UiAppearance.label("Point and bootstrap confidence (0.5–0.9999)"),confidence,UiAppearance.label("Bootstrap attempts"),samples,UiAppearance.label("Random seed"),seed,UiAppearance.label("Bootstrap convention"),convention,UiAppearance.label("Interval method"),interval,twoSided);estimation.setPadding(new Insets(12));samples.setDisable(!resampling);seed.setDisable(!resampling);convention.setDisable(!resampling);interval.setDisable(!resampling);twoSided.setDisable(!resampling);TabPane tabs=new TabPane(new Tab("Model recipe",new ScrollPane(builder)),new Tab("Custom paths and probes",new ScrollPane(advanced)),new Tab("Estimation and bootstrap",new ScrollPane(estimation)));for(var tab:tabs.getTabs()){tab.setClosable(false);((ScrollPane)tab.getContent()).setFitToWidth(true);}Label error=new Label();error.setWrapText(true);builder.disableProperty().bind(custom.selectedProperty());modelJson.disableProperty().bind(custom.selectedProperty().not());probeJson.disableProperty().bind(custom.selectedProperty().not());VBox content=new VBox(8,custom,tabs,error);VBox.setVgrow(tabs,Priority.ALWAYS);content.setPrefSize(800,700);dialog.getDialogPane().setContent(content);dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);
        dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{PathProcess.Model model;List<PathProcess.Probe> probes;if(custom.isSelected()){model=readModel(JsonParser.parseString(modelJson.getText()));probes=readProbes(JsonParser.parseString(probeJson.getText()));}else{int source=names.indexOf(x.getValue()),target=names.indexOf(y.getValue());List<Integer> chosen=new ArrayList<>(mediators.getSelectionModel().getSelectedIndices());if(!mediatorOrder.getText().isBlank()){chosen.clear();for(String token:mediatorOrder.getText().split(","))chosen.add(Integer.parseInt(token.trim())-1);}int[] covariates=controls.getSelectionModel().getSelectedIndices().stream().mapToInt(Integer::intValue).toArray();int moderator=names.indexOf(w.getValue()),second=names.indexOf(z.getValue());model=recipe(template.getValue(),source,target,chosen,moderator,second,covariates);boolean moderated=template.getValue()!=Template.PARALLEL_MEDIATION&&template.getValue()!=Template.SERIAL_MEDIATION;probes=new ArrayList<>();if(moderated)for(double first:values(wValues.getText()))if(template.getValue()==Template.THREE_WAY_MODERATION)for(double other:values(zValues.getText()))probes.add(new PathProcess.Probe(names.get(moderator)+"="+first+"; "+names.get(second)+"="+other,Map.of(moderator,first,second,other)));else probes.add(new PathProcess.Probe(names.get(moderator)+"="+first,Map.of(moderator,first)));}double level=Double.parseDouble(confidence.getText().trim());var settings=new PathProcess.Options(metric.getValue(),covariance.getValue(),level,useControls.isSelected());var bootstrap=resampling?new Bootstrap.Options(Integer.parseInt(samples.getText().trim()),Long.parseLong(seed.getText().trim()),level,interval.getValue(),convention.getValue(),twoSided.isSelected()):boot;validate(names,model,probes);PathProcess.validate(names.size(),names,model,settings,probes);result=new Settings(model,settings,probes,bootstrap);}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);
    }
    private static HBox row(String first,Control a,String second,Control b){VBox left=new VBox(4,new Label(first),a),right=new VBox(4,new Label(second),b);HBox.setHgrow(left,Priority.ALWAYS);HBox.setHgrow(right,Priority.ALWAYS);return new HBox(12,left,right);}
    private static double[] values(String text){double[] values=Arrays.stream(text.split(",")).map(String::trim).mapToDouble(Double::parseDouble).toArray();if(values.length<1||values.length>10||Arrays.stream(values).anyMatch(value->!Double.isFinite(value))||Arrays.stream(values).distinct().count()!=values.length)throw new IllegalArgumentException("Use 1–10 distinct finite probe values per moderator.");return values;}
    private static String defaultValues(double[][] data,int column){if(column<0)return "0";double[] values=Arrays.stream(data).mapToDouble(row->row[column]).sorted().toArray();double[] unique=Arrays.stream(values).distinct().toArray();if(unique.length<=3)return String.join(", ",Arrays.stream(unique).mapToObj(Double::toString).toList());return String.join(", ",Arrays.stream(new double[]{Inference.quantile(values,.16),Inference.quantile(values,.5),Inference.quantile(values,.84)}).mapToObj(value->String.format(Locale.ROOT,"%.6g",value)).toList());}
    static PathProcess.Model recipe(Template template,int x,int y,List<Integer> supplied,int w,int z,int[] controls){List<Integer> mediators=List.copyOf(supplied);boolean modulation=template!=Template.PARALLEL_MEDIATION&&template!=Template.SERIAL_MEDIATION;boolean mediation=template!=Template.MODERATION&&template!=Template.THREE_WAY_MODERATION;if(mediation&&(mediators.isEmpty()||mediators.size()>10||new HashSet<>(mediators).size()!=mediators.size()||mediators.contains(x)||mediators.contains(y)))throw new IllegalArgumentException("Choose 1–10 distinct mediator columns separate from X and Y.");if(modulation&&(w==x||w==y||mediation&&mediators.contains(w)||template==Template.THREE_WAY_MODERATION&&(z==w||z==x||z==y)))throw new IllegalArgumentException("Moderator roles must be distinct.");List<PathProcess.Path> paths=new ArrayList<>();if(!mediation){paths.add(new PathProcess.Path(x,y,template==Template.THREE_WAY_MODERATION?new int[]{w,z}:new int[]{w}));return new PathProcess.Model(x,y,paths,controls);}boolean first=template==Template.FIRST_STAGE_MODERATED_MEDIATION||template==Template.BOTH_STAGES_MODERATED_MEDIATION,second=template==Template.SECOND_STAGE_MODERATED_MEDIATION||template==Template.BOTH_STAGES_MODERATED_MEDIATION;for(int index=0;index<mediators.size();index++){int mediator=mediators.get(index);paths.add(new PathProcess.Path(x,mediator,first?new int[]{w}:new int[0]));if(template==Template.SERIAL_MEDIATION)for(int previous=0;previous<index;previous++)paths.add(new PathProcess.Path(mediators.get(previous),mediator));paths.add(new PathProcess.Path(mediator,y,second?new int[]{w}:new int[0]));}paths.add(new PathProcess.Path(x,y));return new PathProcess.Model(x,y,paths,controls);}
    static PathProcess.Model readModel(JsonElement supplied){return org.brightstats.data.ProcessInput.model(supplied);}
    static List<PathProcess.Probe> readProbes(JsonElement supplied){return org.brightstats.data.ProcessInput.probes(supplied);}
    static void validate(List<String> names,PathProcess.Model model,List<PathProcess.Probe> probes){if(model.source()>=names.size()||model.target()>=names.size())throw new IllegalArgumentException("Process source/outcome is unavailable.");for(var path:model.paths())if(path.source()>=names.size()||path.target()>=names.size()||Arrays.stream(path.moderators()).anyMatch(column->column>=names.size()))throw new IllegalArgumentException("Process path refers to an unavailable column.");for(int control:model.controls())if(control<0||control>=names.size())throw new IllegalArgumentException("Process control is unavailable.");for(var probe:probes)if(probe.values().keySet().stream().anyMatch(column->column>=names.size()))throw new IllegalArgumentException("Process probe column is unavailable.");}
    static Settings smokeTest(Window owner,List<String> names,double[][] data){var test=new ProcessDialog(owner,names,data,null,true);test.dialog.show();test.x.getSelectionModel().select(0);test.y.getSelectionModel().select(0);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Identical process source/outcome accepted");test.y.getSelectionModel().select(3);test.samples.setText("29");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Too few process bootstrap samples accepted");test.samples.setText("40");test.template.setValue(Template.BOTH_STAGES_MODERATED_MEDIATION);test.wValues.setText("-0.5,0,0.5");test.covariance.setValue(RobustRegression.Covariance.HC3);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null)throw new AssertionError("Process settings lost");return test.dialog.getResult();}
    static Optional<Settings> show(Window owner,List<String> names,double[][] data,Settings previous,boolean resampling){return new ProcessDialog(owner,names,data,previous,resampling).dialog.showAndWait();}
}
